    """Merge two sorted lists into one sorted list (duplicates are kept)."""
    merged = []
    a_index = 0
    b_index = 0

    # Merge the lists until one is empty
    while a_index < len(a) or b_index < len(b):
        if a_index == len(a):
            merged.append(b[b_index])
            b_index += 1
        elif b_index == len(b):
            merged.append(a[a_index])
            a_index += 1
        else:
            # Compare the current elements and append the smaller one
            if a[a_index] <= b[b_index]:
                merged.append(a[a_index])
                a_index += 1
            else:
                merged.append(b[b_index])
                b_index += 1

    return merged

