def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams; sort each group alphabetically, then sort the groups."""
    # Sort the words alphabetically
    words.sort()

    # Group the words by the first character
    grouped_words = {word[0]: [word] for word in words}

