def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams; sort each group, then sort the groups."""
    # Create a dictionary to map each sorted word to a list of words that have that word as a prefix
    anagram_map = {}

    for word in words:
        # Create a sorted version of the word
        sorted_word = ''.join(sorted(word))

        # If the sorted word is already in the map, add the word to the list of words for that prefix
        if sorted_word in anagram_map:
            anagram_map[sorted_word].append(word)
        else:
            # If not, create a list with the word and add it to the map with the sorted word as the prefix
            anagram_map[sorted_word] = [word]

    # Collect all the sorted word lists from the map into a list of lists
    groups = [(sub, sorted(sub)) for sub in anagram_map.values()]
    return groups

def two_sum(nums: list[int], target: int) -> list[int]:
    """Return [i, j] (i < j) such that nums[i] + nums[j] == target."""
