    # Initialize a counter for each type of opening bracket
    open_brackets = {'(': 1, '[': 1, '{': 1}
    # Initialize a counter for each type of closing bracket
    close_brackets = {')': -1, ']': -1, '}': -1}

    # Initialize a counter for unmatched opening brackets
    unmatched_open = 0
    # Initialize a counter for unmatched closing brackets
    unmatched_close = 0

    # Iterate through each character in the string
    for char in s:
        if char in open_brackets:
            # Increment the counter for the current opening bracket
            open_brackets[char] += 1
        elif char in close_brackets:
            # Decrement the counter for the current closing bracket
            close_brackets[char] -= 1

            # If the counter for the closing bracket is negative, it means we have a closing bracket without a matching opening bracket
            if close_brackets[char] < 0:
                return False

            # If the counter for the opening bracket is negative, it means we have an unmatched opening bracket
            if open_brackets[char] < 0:
